class Solution {
  private int idx(char c) {
    if (c == 'R') return 0;
    if (c == 'Y') return 1;
    if (c == 'G') return 2;
    return 3;
  }

  public int[] masterMind(String solution, String guess) {
    int hits = 0;
    int[] sCount = new int[4], gCount = new int[4];
    for (int i = 0; i < solution.length(); i++) {
      if (solution.charAt(i) == guess.charAt(i)) {
        hits++;
      } else {
        sCount[idx(solution.charAt(i))]++;
        gCount[idx(guess.charAt(i))]++;
      }
    }
    int pseudo = 0;
    for (int i = 0; i < 4; i++) pseudo += Math.min(sCount[i], gCount[i]);
    return new int[] { hits, pseudo };
  }
}

class Solution:
    def masterMind(self, solution: str, guess: str) -> List[int]:
        hits = 0
        s_count = Counter()
        g_count = Counter()
        for s, g in zip(solution, guess):
            if s == g:
                hits += 1
            else:
                s_count[s] += 1
                g_count[g] += 1
        pseudo = sum((s_count & g_count).values())
        return [hits, pseudo]

impl Solution {
  pub fn master_mind(solution: String, guess: String) -> Vec<i32> {
    let s = solution.as_bytes();
    let g = guess.as_bytes();
    let idx = |c: u8| -> usize {
      match c {
        b'R' => 0,
        b'Y' => 1,
        b'G' => 2,
        _ => 3,
      }
    };
    let mut hits = 0;
    let mut s_count = [0i32; 4];
    let mut g_count = [0i32; 4];
    for i in 0..s.len() {
      if s[i] == g[i] {
        hits += 1;
      } else {
        s_count[idx(s[i])] += 1;
        g_count[idx(g[i])] += 1;
      }
    }
    let pseudo: i32 = (0..4).map(|i| s_count[i].min(g_count[i])).sum();
    vec![hits, pseudo]
  }
}

const masterMind = (solution: string, guess: string): number[] => {
  let hits = 0;
  const sCount: Record<string, number> = {};
  const gCount: Record<string, number> = {};
  for (let i = 0; i < solution.length; i++) {
    if (solution[i] === guess[i]) {
      hits++;
    } else {
      sCount[solution[i]] = (sCount[solution[i]] ?? 0) + 1;
      gCount[guess[i]] = (gCount[guess[i]] ?? 0) + 1;
    }
  }
  let pseudo = 0;
  for (const c of Object.keys(sCount)) {
    pseudo += Math.min(sCount[c], gCount[c] ?? 0);
  }
  return [hits, pseudo];
};
